mapper.select:
SELECT id,role_name AS roleName,permissions,`desc`,default_permissions AS defaultPermissions
FROM `role`
WHERE id = #{id}

SELECT r.id, r.role_name AS roleName, COUNT( u.id ) AS users, JSON_LENGTH ( r.permissions ) AS permissions, r.`desc`, r.systemic FROM role r LEFT JOIN users u ON JSON_CONTAINS ( u.role, CONVERT ( r.id, CHAR ) ) WHERE 1=1
AND r.role_name LIKE '%${roleName}%'
GROUP BY r.id ORDER BY r.id LIMIT #{start}, #{length}

SELECT IF( SUM( temp.users ) > 0, FALSE, TRUE ) AS result FROM ( SELECT COUNT( u.id ) AS users FROM role r JOIN users u ON JSON_CONTAINS ( u.role, CONVERT ( r.id, CHAR ) ) WHERE r.id IN
#{one}
GROUP BY r.id ) temp

mapper.insert:
INSERT INTO role
SET role_name=#{roleName},
permissions=#{permissions}

    ,`desc`=#{desc}

mapper.delete:
DELETE FROM role WHERE id IN
#{one}
AND systemic=FALSE
